import { ConstraintViolationError } from "../../errors";

/**
 * The part of a `PrismaClient` the adapter uses: raw SQL with bound parameters. Any client
 * generated by `prisma generate` (Prisma 5+, with or without a driver adapter, `$extends`
 * included) fits; the adapter never touches the app's generated model delegates.
 */
export interface PrismaQueryable {
  $queryRawUnsafe<T = unknown>(query: string, ...values: unknown[]): PromiseLike<T>;
  $executeRawUnsafe(query: string, ...values: unknown[]): PromiseLike<number | bigint>;
}

/** A `PrismaClient` (interactive transactions are used for the multi-statement operations). */
export interface PrismaClientLike extends PrismaQueryable {
  $transaction<R>(
    fn: (tx: PrismaQueryable) => Promise<R>,
    options?: { maxWait?: number; timeout?: number },
  ): PromiseLike<R>;
}

/**
 * A query failed for a reason the adapter does not map to a library error (connection
 * refused, missing table, permission denied, an undocumented constraint...).
 */
export class PrismaAdapterError extends Error {
  /** Postgres SQLSTATE (e.g. `23503`, `42P01`), or `null`. */
  readonly code: string | null;
  /** The adapter operation, e.g. `messages.insertOutbound`. */
  readonly operation: string;

  constructor(operation: string, error: unknown) {
    const failure = dbFailure(error);
    super(`sendo prisma adapter: ${operation} failed: ${failure.message}`, { cause: error });
    this.name = "PrismaAdapterError";
    this.operation = operation;
    this.code = failure.code;
  }
}

export const PG_UNIQUE_VIOLATION = "23505";
export const PG_CHECK_VIOLATION = "23514";
export const PG_FOREIGN_KEY_VIOLATION = "23503";
export const PG_UNDEFINED_TABLE = "42P01";

export interface DbFailure {
  /** SQLSTATE, or `null` when the error did not come from Postgres. */
  code: string | null;
  message: string;
  /** Constraint or index named by the error, or `null`. */
  constraint: string | null;
}

const SQLSTATE_RE = /^[0-9A-Z]{5}$/;

function record(value: unknown): Record<string, unknown> | null {
  return typeof value === "object" && value !== null ? (value as Record<string, unknown>) : null;
}

function str(value: unknown): string | null {
  return typeof value === "string" && value !== "" ? value : null;
}

/**
 * SQLSTATE, message and constraint of a raw-query failure. Prisma 7 driver adapters report
 * them in `meta.driverAdapterError.cause` (`originalCode`, `originalMessage`); the Rust engine
 * (Prisma 5/6) in `meta.code` / `meta.message`; `pg` errors carry `code` / `constraint`.
 */
export function dbFailure(error: unknown): DbFailure {
  const err = record(error);
  const meta = record(err?.meta);
  const cause = record(record(meta?.driverAdapterError)?.cause);
  const message =
    str(cause?.originalMessage) ??
    str(cause?.message) ??
    str(meta?.message) ??
    str(err?.message) ??
    String(error);
  const candidates = [cause?.originalCode, cause?.code, meta?.code, err?.code];
  let code = candidates.map(str).find((c): c is string => c !== null && SQLSTATE_RE.test(c));
  code ??= /Code: `([0-9A-Z]{5})`/.exec(str(err?.message) ?? "")?.[1];
  const named =
    str(record(cause?.constraint)?.index) ?? str(err?.constraint) ?? str(cause?.constraint);
  const constraint = named ?? /constraint "([^"]+)"/.exec(message)?.[1] ?? null;
  return { code: code ?? null, message, constraint };
}

export function isUniqueViolation(error: unknown, constraint?: string): boolean {
  const failure = dbFailure(error);
  if (failure.code !== PG_UNIQUE_VIOLATION) return false;
  return constraint === undefined || failure.constraint === constraint;
}

/**
 * `ConstraintViolationError` when `error` broke one of `constraints` (the schema rules every
 * adapter enforces), else `PrismaAdapterError`.
 */
export function writeFailure(
  operation: string,
  error: unknown,
  constraints: readonly string[],
): ConstraintViolationError | PrismaAdapterError {
  const failure = dbFailure(error);
  const violation = failure.code === PG_UNIQUE_VIOLATION || failure.code === PG_CHECK_VIOLATION;
  if (violation && failure.constraint !== null && constraints.includes(failure.constraint)) {
    return new ConstraintViolationError({ constraint: failure.constraint }, { cause: error });
  }
  return new PrismaAdapterError(operation, error);
}

export const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
/** A malformed id can never match a row: reads return null, updates throw not found. */
export const isUuid = (value: string): boolean => UUID_RE.test(value);

/** Bound parameters of one statement: `add` returns the placeholder (`$n`, optionally cast). */
export class Params {
  readonly values: unknown[] = [];

  add(value: unknown, cast?: string): string {
    this.values.push(value);
    return cast ? `$${String(this.values.length)}::${cast}` : `$${String(this.values.length)}`;
  }
}

/** Columns stored as `jsonb`: written as JSON text (SQL `NULL` for `null`). */
const JSON_COLUMNS = new Set([
  "content",
  "error",
  "metadata",
  "components",
  "payload",
  "params",
  "state",
  "variables",
]);

/** A column value as a bound parameter (`jsonb` as JSON text, dates as ISO strings). */
export function columnParam(params: Params, column: string, value: unknown): string {
  if (JSON_COLUMNS.has(column)) {
    return params.add(value === null ? null : JSON.stringify(value), "jsonb");
  }
  return params.add(value instanceof Date ? value.toISOString() : value);
}

/** `"col" = $n, ...` for the defined values (empty string when there are none). */
export function setClause(params: Params, values: Record<string, unknown>): string {
  return Object.entries(values)
    .filter(([, value]) => value !== undefined)
    .map(([column, value]) => `${column} = ${columnParam(params, column, value)}`)
    .join(", ");
}

/** `(cols) values (...)` for the defined values. */
export function insertClause(params: Params, values: Record<string, unknown>): string {
  return insertRowsClause(params, [values]);
}

/** `(cols) values (...), (...)`: the columns are the first row's defined values. */
export function insertRowsClause(params: Params, rows: Record<string, unknown>[]): string {
  const columns = Object.keys(rows[0] ?? {}).filter((column) => rows[0]?.[column] !== undefined);
  const tuples = rows.map(
    (row) => `(${columns.map((column) => columnParam(params, column, row[column])).join(", ")})`,
  );
  return `(${columns.join(", ")}) values ${tuples.join(", ")}`;
}

/** `column is not distinct from $n::uuid` (a `null` tenant matches rows without a tenant). */
export function tenantMatch(params: Params, column: string, tenantId: string | null): string {
  return `${column} is not distinct from ${params.add(tenantId, "uuid")}`;
}

/** A Postgres identifier in double quotes. */
export function quoteIdent(name: string): string {
  return `"${name.replace(/"/g, '""')}"`;
}

/** Outcome of `Db.attempt`: the rows, or the raw failure. */
export type Attempt<T> = { failed: false; rows: T[] } | { failed: true; error: unknown };

/**
 * Runs raw SQL on a Prisma client (or a transaction client). Rows are read as `to_jsonb(...)`
 * so every Prisma version returns the same JSON shape PostgREST does (ISO timestamps with
 * microseconds, numbers for `numeric`, strings for enums), and the Supabase row mappers apply.
 */
export class Db {
  constructor(
    readonly client: PrismaQueryable,
    /** `"schema".` prefix for every `sendo_*` table. */
    readonly prefix: string,
  ) {}

  /** `"schema".sendo_x`. */
  t(table: string): string {
    return `${this.prefix}${table}`;
  }

  async query<T>(operation: string, sql: string, params: Params | unknown[]): Promise<T[]> {
    const values = params instanceof Params ? params.values : params;
    try {
      return await this.client.$queryRawUnsafe<T[]>(sql, ...values);
    } catch (error) {
      throw new PrismaAdapterError(operation, error);
    }
  }

  /** Like `query`, but lets the caller map failures (constraints) itself. */
  async attempt<T>(sql: string, params: Params): Promise<Attempt<T>> {
    try {
      return { failed: false, rows: await this.client.$queryRawUnsafe<T[]>(sql, ...params.values) };
    } catch (error) {
      return { failed: true, error };
    }
  }

  /** Rows selected as `to_jsonb(x.*) as row`. */
  async rows<T>(operation: string, sql: string, params: Params): Promise<T[]> {
    const result = await this.query<{ row: T }>(operation, sql, params);
    return result.map((r) => r.row);
  }

  async row<T>(operation: string, sql: string, params: Params): Promise<T | null> {
    return (await this.rows<T>(operation, sql, params))[0] ?? null;
  }

  /** Affected row count. */
  async execute(operation: string, sql: string, params: Params): Promise<number> {
    try {
      return Number(await this.client.$executeRawUnsafe(sql, ...params.values));
    } catch (error) {
      throw new PrismaAdapterError(operation, error);
    }
  }
}
